return ['x-generator'=>'GlotPress/4.1.0','translation-revision-date'=>'2026-10-09 09:57:54+0000','plural-forms'=>'nplurals=3; plural=(n % 10 == 1 && n % 100 != 11) ? 0 : ((n % 10 >= 2 && n % 10 <= 4 && (n % 100 < 12 || n % 100 > 14)) ? 1 : 2);','project-id-version'=>'Plugins - Jetpack &#8211; WP Security, Backup, Speed, &amp; Growth - Stable (latest release)','language'=>'ru','messages'=>['block keywordappointment'=>'встреча','block keywordscheduling'=>'планирование','block descriptionEmbed a Zoom Scheduler booking page.'=>'Встроить страницу бронирования Zoom Scheduler','block titleZoom Scheduler'=>'Zoom Scheduler','block keyworddynamic'=>'динамические','block keywordrecent'=>'недавние','block keywordnewest'=>'новые','block keywordlatest'=>'последние','block descriptionVideoPress powered list of your latest videos in a single customizable player. New uploads show up automatically.'=>'Список последних видео на базе VideoPress в одном настраиваемом плеере. Новые загрузки появляются автоматически.','block titleLatest Videos Playlist'=>'Плейлист последних видео','block keywordcollection'=>'коллекция','block keywordplaylists'=>'плейлисты','block descriptionEvery playlist on the site, paginated, under a heading you can edit.'=>'Все плейлисты на сайте, с постраничной навигацией, под заголовком, который можно редактировать.','block titleAll Playlists'=>'Все плейлисты','block keywordpayment'=>'payment','block keywordpaypal'=>'paypal','block descriptionAccept payments via PayPal. Create a buy button directly in the editor — no code required.'=>'Принимайте платежи через PayPal. Создайте кнопку покупки прямо в редакторе — программировать не требуется.','The site verification code is invalid.'=>'Неверный проверочный код для сайта.','The requested Jetpack module is enabled by your host or site administrator, so it stays on.'=>'Запрошенный модуль Jetpack включён хостинг-провайдером или администратором сайта, поэтому он работает.','The requested Jetpack module is disabled by your host or site administrator, so it stays off.'=>'Запрошенный модуль Jetpack отключён хостинг-провайдером или администратором сайта, поэтому он не работает.','%s must be a valid verification code or verification tag.'=>'%s должно быть действительным проверочным кодом или тегом подтверждения.','Jetpack AI could not be loaded because its assets are missing. Reinstalling or updating the plugin usually fixes this. If it keeps happening, contact your site administrator or host.'=>'Не удалось загрузить Jetpack AI, так как отсутствуют его ресурсы. Обычно это решается переустановкой или обновлением плагина. Если проблема повторится, обратитесь к администратору сайта или хостинг-провайдеру.','Email Design'=>'Дизайн писем','Module DescriptionA record of every event on your site, so you can see what happened and roll back when something goes wrong.'=>'Запись всех событий на вашем сайте: вы всегда сможете посмотреть, что произошло, и выполнить откат, если что-то пойдёт не так.','Module NameActivity Log'=>'Журнал активности','Invalid site verification code. Enter a verification code or verification tag.'=>'Неверный проверочный код для сайта. Введите проверочный код или тег подтверждения.','This video could not be found in the Media Library. Restore it from the trash, if available, and try again.'=>'Это видео не найдено в библиотеке файлов. Восстановите его из корзины, если оно там есть, и повторите попытку.','The video editing service returned an invalid response.'=>'Служба редактирования видео вернула некорректный ответ.','Trim and cut operations on the original video timeline.'=>'Операции обрезки и вырезания на исходной временной шкале видео.','The revision the edits are based on.'=>'Редакция, на которой основаны правки.','If videos should render an inline player from one shared script instead of one frame per video'=>'Определяет, использовать ли один общий скрипт для встроенного плеера вместо создания отдельного фрейма для каждого видео.','Play video'=>'Воспро